function document(locale: ExpansionLegalLocale, page: LegalPage, bodyHtml: string): ExpansionLegalDocument {
  const [title, description] = labels[locale][page];
  return {
    title,
    description,
    eyebrow: locale === "es" ? "Información legal" : locale === "it" ? "Informazioni legali" : "Informations juridiques",
    updated: locale === "es" ? "27 de octubre de 2026" : locale === "it" ? "27 ottobre 2026" : "27 octobre 2026",
    noticeHtml: notices[locale][page],
    bodyHtml,
  };
}

